function validate(input) {
  const [{ Logins = [] }] = input;
  const stamp = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/;
  const seen = new Set();
  for (const [user, time] of Logins) {
    if (user === null) return 'Every login needs a user_id.';
    if (!stamp.test(String(time))) return `User ${user} has a malformed time_stamp.`;
    const key = `${user}|${time}`;
    if (seen.has(key)) return `User ${user} logs in twice at ${time}.`;
    seen.add(key);
  }
  return null;
}

