function generate(rand, size) {
  const pad = n => String(n).padStart(2, '0');
  const pick = list => list[Math.floor(rand() * list.length)];
  // Instants right at the edges of 2020 make the year filter's boundaries matter.
  const edges = ['2019-12-31 23:59:59', '2020-01-01 00:00:00', '2020-12-31 23:59:59', '2021-01-01 00:00:00', '2020-12-31 08:15:00'];
  const small = size === 'small';
  const rows = small ? Math.floor(rand() * 9) : 2000;
  const users = small ? 4 : 300;
  const stamp = () => {
    if (rand() < (small ? 0.25 : 0.05)) return pick(edges);
    const year = pick([2019, 2020, 2020, 2021]);
    return `${year}-${pad(1 + Math.floor(rand() * 12))}-${pad(1 + Math.floor(rand() * 28))} ${pad(Math.floor(rand() * 24))}:${pad(Math.floor(rand() * 60))}:${pad(Math.floor(rand() * 60))}`;
  };
  const Logins = [], seen = new Set();
  for (let tries = 0; Logins.length < rows && tries < rows * 4; tries++) {
    const row = [1 + Math.floor(rand() * users), stamp()];
    const key = row.join('|');
    if (seen.has(key)) continue;
    seen.add(key);
    Logins.push(row);
  }
  return [{ Logins }];
}
